    31	    public ItemResource selected() {
    32	        for (FertilizerBlockEntity block : live()) {
    33	            ItemStacksResourceHandler storage = block.storage();
    34	            for (int slot = 0; slot < storage.size(); slot++) {
    35	                ItemResource resource = storage.getResource(slot);
    36	                if (!resource.isEmpty()) {
    37	                    return resource;
    38	                }
    39	            }
    40	        }
    41	        return ItemResource.EMPTY;
    42	    }
    43	
    44	    public int available() {
    45	        ItemResource selected = selected();
    46	        if (selected.isEmpty()) {
    47	            return 0;
    48	        }
    49	        long total = 0;
    50	        for (FertilizerBlockEntity block : live()) {
    51	            ItemStacksResourceHandler storage = block.storage();
    52	            for (int slot = 0; slot < storage.size(); slot++) {
    53	                if (storage.getResource(slot).equals(selected)) {
    54	                    total += storage.getAmountAsLong(slot);
    55	                }
    56	            }
    57	        }
    58	        return (int) Math.min(total, Integer.MAX_VALUE);
    59	    }
