    66	    public boolean consume(int count) {
    67	        ItemResource selected = selected();
    68	        if (selected.isEmpty() || count < 0) {
    69	            return false;
    70	        }
    71	        try (Transaction tx = Transaction.openRoot()) {
    72	            int remaining = count;
    73	            for (FertilizerBlockEntity block : live()) {
    74	                if (remaining == 0) {
    75	                    break;
    76	                }
    77	                remaining -= block.storage().extract(selected, remaining, tx);
    78	            }
    79	            if (remaining > 0) {
    80	                return false;
    81	            }
    82	            tx.commit();
    83	            return true;
    84	        }
    85	    }
