    96	    // Every planter block of a core claims from one budget per tick, in the position order the core ticks them, so claims never add up to more than the pool held when the tick started, and a claim takes items only when its group harvests, one per seed.
    97	    public static final class Budget {
    98	        private final FertilizerPool pool;
    99	        private final @Nullable FertilizerData data;
   100	        private int unclaimed;
   101	
   102	        private Budget(FertilizerPool pool, @Nullable FertilizerData data, int unclaimed) {
   103	            this.pool = pool;
   104	            this.data = data;
   105	            this.unclaimed = unclaimed;
   106	        }
