     5	import java.util.ArrayList;
     6	import java.util.List;
     7	
     8	final class LiveBlocks {
     9	    private LiveBlocks() {
    10	    }
    11	
    12	    // A pool is only rebuilt when the core's scan changes, so a block broken or unloaded since then is still listed.
    13	    // This returns only the blocks that are not removed and asks the core to rescan when it finds a removed one.
    14	    static <T extends BlockEntity> List<T> of(List<T> blocks, Runnable onStale) {
    15	        List<T> live = new ArrayList<>(blocks.size());
    16	        boolean stale = false;
    17	        for (T block : blocks) {
    18	            if (block.isRemoved()) {
    19	                stale = true;
    20	            } else {
    21	                live.add(block);
    22	            }
    23	        }
    24	        if (stale) {
    25	            onStale.run();
    26	        }
    27	        return live;
    28	    }
    29	}

