   109	        poolsStale = false;
   110	        ScanResult<BlockPos> result = StructureScanner.scan(worldPosition,
   111	                pos -> Arrays.stream(Direction.values()).map(pos::relative).toList(),
   112	                pos -> typeAt(level, pos), MPConfig.PART_CAP.get());
   113	        if (result.equals(lastScan) && !rebuild) {
   114	            return;
   115	        }
   116	        lastScan = result;
   117	        if (result.problem() == Problem.WAITING_FOR_CHUNKS) {
   118	            // The multiblock is kept so a structure with an unloaded part pauses instead of unforming, while the pools are dropped so nothing touches a block entity in an unloaded chunk.
   119	            power = null;
   120	            fertilizer = null;
   121	            outputs = null;
   122	        } else {
