   153	            power = null;
   154	            fertilizer = null;
   155	            outputs = null;
   156	            return;
   157	        }
   158	        power = new PowerPool(blockEntities(level, multiblock.power(), PowerBlockEntity.class), this::markPoolsStale);
   159	        fertilizer = new FertilizerPool(blockEntities(level, multiblock.fertilizer(), FertilizerBlockEntity.class), this::markPoolsStale);
   160	        outputs = new OutputSink(blockEntities(level, multiblock.export(), ExportBlockEntity.class), this::markPoolsStale);
   161	    }
