package io.github.julianperge.modular_planters.multiblock;

import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.transfer.CombinedResourceHandler;
import net.neoforged.neoforge.transfer.DelegatingResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandlerUtil;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.item.ItemStacksResourceHandler;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jetbrains.annotations.Nullable;

import java.util.List;

public final class OutputSink {
    private final List<ExportBlockEntity> blocks;
    private final Runnable onStale;
    private final ResourceHandler<ItemResource> extractView = new DelegatingResourceHandler<>(
            () -> new CombinedResourceHandler<>(live().stream().map(ExportBlockEntity::externalHandler).toList()));

    public OutputSink(List<ExportBlockEntity> inOrder, Runnable onStale) {
        this.blocks = List.copyOf(inOrder);
        this.onStale = onStale;
    }

    private List<ExportBlockEntity> live() {
        return LiveBlocks.of(blocks, onStale);
    }

    public boolean hasRoomFor(List<ItemStack> stacks) {
        try (Transaction tx = Transaction.openRoot()) {
            for (ItemStack stack : stacks) {
                if (!insertInto(stack, tx).isEmpty()) {
                    return false;
                }
            }
            return true;
        }
    }

    public ItemStack insert(ItemStack stack) {
        return insertInto(stack, null);
    }

    public ResourceHandler<ItemResource> extractView() {
        return extractView;
    }

    public int fillPercent() {
        long stored = 0;
        long capacity = 0;
        for (ExportBlockEntity block : live()) {
            ItemStacksResourceHandler storage = block.storage();
            for (int slot = 0; slot < storage.size(); slot++) {
                stored += storage.getAmountAsLong(slot);
                capacity += storage.getCapacityAsLong(slot, storage.getResource(slot));
            }
        }
        return capacity == 0 ? 0 : (int) (stored * 100 / capacity);
    }

    private ItemStack insertInto(ItemStack stack, @Nullable TransactionContext transaction) {
        if (stack.isEmpty()) {
            return ItemStack.EMPTY;
        }
        ItemResource resource = ItemResource.of(stack);
        int remaining = stack.getCount();
        for (ExportBlockEntity block : live()) {
            if (remaining == 0) {
                break;
            }
            remaining -= ResourceHandlerUtil.insertStacking(block.storage(), resource, remaining, transaction);
        }
        return remaining == 0 ? ItemStack.EMPTY : resource.toStack(remaining);
    }
}
package io.github.julianperge.modular_planters.multiblock;

import io.github.julianperge.modular_planters.blockentity.PowerBlockEntity;
import net.neoforged.neoforge.transfer.energy.EnergyHandler;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;

import java.util.List;

public final class PowerPool {
    private final List<PowerBlockEntity> blocks;
    private final Runnable onStale;
    private final EnergyHandler insertView = new InsertView();

    public PowerPool(List<PowerBlockEntity> inOrder, Runnable onStale) {
        this.blocks = List.copyOf(inOrder);
        this.onStale = onStale;
    }

    private List<PowerBlockEntity> live() {
        return LiveBlocks.of(blocks, onStale);
    }

    public long stored() {
        long total = 0;
        for (PowerBlockEntity block : live()) {
            total += block.stored();
        }
        return total;
    }

    public long capacity() {
        long total = 0;
        for (PowerBlockEntity block : live()) {
            total += block.capacity();
        }
        return total;
    }

    public boolean tryTake(long amount) {
        if (amount < 0 || stored() < amount) {
            return false;
        }
        long remaining = amount;
        for (PowerBlockEntity block : live()) {
            int taken = (int) Math.min(remaining, block.stored());
            if (taken > 0) {
                block.setStored(block.stored() - taken);
                remaining -= taken;
            }
        }
        return true;
    }

    public EnergyHandler insertView() {
        return insertView;
    }

    private final class InsertView implements EnergyHandler {
        @Override
        public long getAmountAsLong() {
            return stored();
        }

        @Override
        public long getCapacityAsLong() {
            return capacity();
        }

        @Override
        public int insert(int amount, TransactionContext transaction) {
            int inserted = 0;
            for (PowerBlockEntity block : live()) {
                if (inserted == amount) {
                    break;
                }
                inserted += block.externalHandler().insert(amount - inserted, transaction);
            }
            return inserted;
        }

        @Override
        public int extract(int amount, TransactionContext transaction) {
            return 0;
        }
    }
}
package io.github.julianperge.modular_planters.multiblock;

import com.misterd.agritechevolved.datamap.FertilizerData;
import io.github.julianperge.modular_planters.ate.AteBridge;
import io.github.julianperge.modular_planters.blockentity.FertilizerBlockEntity;
import net.neoforged.neoforge.transfer.CombinedResourceHandler;
import net.neoforged.neoforge.transfer.DelegatingResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandler;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.item.ItemStacksResourceHandler;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import org.jetbrains.annotations.Nullable;

import java.util.List;

public final class FertilizerPool {
    private final List<FertilizerBlockEntity> blocks;
    private final Runnable onStale;
    private final ResourceHandler<ItemResource> insertView = new DelegatingResourceHandler<>(
            () -> new CombinedResourceHandler<>(live().stream().map(FertilizerBlockEntity::externalHandler).toList()));

    public FertilizerPool(List<FertilizerBlockEntity> inOrder, Runnable onStale) {
        this.blocks = List.copyOf(inOrder);
        this.onStale = onStale;
    }

    private List<FertilizerBlockEntity> live() {
        return LiveBlocks.of(blocks, onStale);
    }

    public ItemResource selected() {
        for (FertilizerBlockEntity block : live()) {
            ItemStacksResourceHandler storage = block.storage();
            for (int slot = 0; slot < storage.size(); slot++) {
                ItemResource resource = storage.getResource(slot);
                if (!resource.isEmpty()) {
                    return resource;
                }
            }
        }
        return ItemResource.EMPTY;
    }

    public int available() {
        ItemResource selected = selected();
        if (selected.isEmpty()) {
            return 0;
        }
        long total = 0;
        for (FertilizerBlockEntity block : live()) {
            ItemStacksResourceHandler storage = block.storage();
            for (int slot = 0; slot < storage.size(); slot++) {
                if (storage.getResource(slot).equals(selected)) {
                    total += storage.getAmountAsLong(slot);
                }
            }
        }
        return (int) Math.min(total, Integer.MAX_VALUE);
    }

    public @Nullable FertilizerData data() {
        ItemResource selected = selected();
        return selected.isEmpty() ? null : AteBridge.fertilizer(selected);
    }

    public boolean consume(int count) {
        ItemResource selected = selected();
        if (selected.isEmpty() || count < 0) {
            return false;
        }
        try (Transaction tx = Transaction.openRoot()) {
            int remaining = count;
            for (FertilizerBlockEntity block : live()) {
                if (remaining == 0) {
                    break;
                }
                remaining -= block.storage().extract(selected, remaining, tx);
            }
            if (remaining > 0) {
                return false;
            }
            tx.commit();
            return true;
        }
    }

    public ResourceHandler<ItemResource> insertView() {
        return insertView;
    }

    public Budget budget() {
        FertilizerData data = data();
        return new Budget(this, data, data == null ? 0 : available());
    }

    // Every planter block of a core claims from one budget per tick, in the position order the core ticks them, so claims never add up to more than the pool held when the tick started, and a claim takes items only when its group harvests, one per seed.
    public static final class Budget {
        private final FertilizerPool pool;
        private final @Nullable FertilizerData data;
        private int unclaimed;

        private Budget(FertilizerPool pool, @Nullable FertilizerData data, int unclaimed) {
            this.pool = pool;
            this.data = data;
            this.unclaimed = unclaimed;
        }

        public @Nullable FertilizerData claim(int seeds) {
            if (data == null || seeds > unclaimed) {
                return null;
            }
            unclaimed -= seeds;
            return data;
        }

        public void consume(int count) {
            pool.consume(count);
        }
    }
}

